            ["Force your name to render uppercase."] = "Fuerza que tu nombre se muestre en mayúsculas.",
            ["Force-start unlocks at {0} signups ({1}/{2})"] = "El inicio forzado se desbloquea con {0} inscritos ({1}/{2})",
            ["Force-start votes: {0}/{1}"] = "Votos de inicio forzado: {0}/{1}",
