            ["No recent series"] = "Sin series",
            ["No server-issued chat lines are in this session's log.\n\nOnly messages this client received from the server can be deleted - the request keys on the server's row id, which a local echo does not carry."] = "No hay líneas de chat del servidor en el registro de esta sesión.\n\nSolo se pueden borrar los mensajes que este cliente recibió del servidor - la petición usa el id de fila del servidor, que un eco local no lleva.",
            ["Noobie"] = "Noobie",
            ["Not enough players to continue the FFA - returning to menu."] = "No hay jugadores suficientes para seguir el FFA - volviendo al menú.",
            ["Not great. Not terrible."] = "No es genial. No es terrible.",
            ["Not in queue."] = "Fuera de cola.",
