            ["Chat fade after: <color=#FF9966>Off (chat hidden in game)</color>"] = "El chat se desvanece tras: <color=#FF9966>Desactivado (chat oculto en partida)</color>",
            ["Chat overlay: MUTED - hidden, and the room is told"] = "Chat superpuesto: SILENCIADO - oculto, y la sala lo sabe",
