            ["Chat overlay: PINNED - messages stay on screen"] = "Chat superpuesto: FIJADO - los mensajes permanecen en pantalla",
            ["Click MAIN MENU again to leave the match."] = "Haz clic en MAIN MENU otra vez para salir de la partida.",
            ["Export already in progress..."] = "Exportación ya en curso...",
            ["Game records (all players) - hover a row for the cards"] = "Récords de partida (todos los jugadores) - pasa el cursor por una fila para ver las cartas",
