            ["Finish or leave your current game before joining the 1v2 queue."] = "Закончите или покиньте текущую игру, прежде чем вставать в очередь 1v2.",
            ["Finish or leave your current game before joining the FFA queue."] = "Закончите или покиньте текущую игру, прежде чем вставать в очередь FFA.",
            ["Finish or leave your current game first."] = "Сначала закончите или покиньте текущую игру.",
            ["Finishing your previous leave first..."] = "Сначала завершаем прошлый выход...",
            ["First to:"] = "Игра до:",
            ["Flag marked as confirmed."] = "Флаг подтверждён.",
            ["Flag marked false positive."] = "Флаг: ложное срабатывание.",
            ["Flag review failed: "] = "Ошибка проверки флага: ",
            ["Flagged Matches"] = "Помеченные матчи",
