            ["Team: Any"] = "Команда: любая",
            ["Teams will rebalance next match!"] = "Команды перебалансируются в следующем матче!",
            ["Thanks for testing the mod during beta. Free, removed after beta ends."] = "Спасибо, что тестил мод в бете. Бесплатно; исчезнет после завершения беты.",
            ["Thanks!"] = "Спасибо!",
            ["That FFA lobby is private — enter its password."] = "Это лобби FFA приватное — введи пароль.",
            ["That game is no longer live."] = "Эта игра уже не идёт.",
