            ["That FFA lobby is private — enter its password."] = "Den FFA-lobbyn är privat — ange dess lösenord.",
            ["That game is no longer live."] = "Den matchen pågår inte längre.",
            ["That {0} lobby is private — enter its password."] = "Den {0}-lobbyn är privat — ange dess lösenord.",
